CREATE TABLE "SmsPlatformSettings" ("id" TEXT NOT NULL DEFAULT 'global', "enabled" BOOLEAN NOT NULL DEFAULT false, "provider" TEXT NOT NULL DEFAULT 'BMS_AFRICA', "senderId" TEXT, "maxDailySegments" INTEGER NOT NULL DEFAULT 10000, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SmsPlatformSettings_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SmsSchoolSettings" ("id" TEXT NOT NULL, "schoolId" TEXT NOT NULL, "enabled" BOOLEAN NOT NULL DEFAULT false, "monthlySegmentLimit" INTEGER NOT NULL DEFAULT 1000, "entryExitEnabled" BOOLEAN NOT NULL DEFAULT false, "announcementsEnabled" BOOLEAN NOT NULL DEFAULT false, "reportCardsEnabled" BOOLEAN NOT NULL DEFAULT false, "staffAlertsEnabled" BOOLEAN NOT NULL DEFAULT false, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SmsSchoolSettings_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "SmsSchoolSettings_schoolId_key" ON "SmsSchoolSettings"("schoolId");
CREATE TABLE "SmsDeliveryLog" ("id" TEXT NOT NULL, "schoolId" TEXT, "eventType" TEXT NOT NULL, "recipient" TEXT NOT NULL, "messagePreview" VARCHAR(500) NOT NULL, "status" TEXT NOT NULL DEFAULT 'QUEUED', "provider" TEXT NOT NULL DEFAULT 'BMS_AFRICA', "providerCampaignId" TEXT, "segments" INTEGER NOT NULL DEFAULT 1, "providerCreditUsed" INTEGER, "errorCode" TEXT, "errorMessage" VARCHAR(500), "idempotencyKey" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SmsDeliveryLog_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "SmsDeliveryLog_idempotencyKey_key" ON "SmsDeliveryLog"("idempotencyKey");
CREATE INDEX "SmsDeliveryLog_schoolId_createdAt_idx" ON "SmsDeliveryLog"("schoolId", "createdAt");
CREATE INDEX "SmsDeliveryLog_status_createdAt_idx" ON "SmsDeliveryLog"("status", "createdAt");
CREATE INDEX "SmsDeliveryLog_eventType_createdAt_idx" ON "SmsDeliveryLog"("eventType", "createdAt");
